    const b = Math.min(Math.max(0, (r && r.b) | 0), books.length - 1);
    const c = Math.min(Math.max(1, (r && r.c) | 0), books[b].ch.length);
    const v = Math.min(Math.max(1, (r && r.v) | 0), books[b].ch[c - 1]);
