  s.mode = s.mode === "pace" ? "pace" : "days";
  s.days = Math.min(Math.max(1, s.days | 0), 3650);
  s.otPer = Math.min(Math.max(1, s.otPer | 0), T.ot.total);
  s.ntPer = Math.min(Math.max(1, s.ntPer | 0), T.nt.total);
  s.repeat = s.repeat !== false;
  if (!VERSIONS.some(v => v[0] === s.version)) s.version = "NIV";
